@classmethod
def from_hex(cls, hex):
    if isinstance(hex, bytes):
        hex = hex.decode('ascii')
    if hex == '':
        return cls('')
    if not hex.startswith('0x'):
        hex = '0x' + hex
    return cls(hex)

@classmethod
def from_int(cls, int_, len_=None):
    return cls(int_, len_)
